# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
M=[['拉丁 mergere，分词 mersus','浸入、沉下去']]
MG=M+[['英语 merge','沉入、被吸收 → 合并、汇成一体']]
EM=M+[['拉丁 ē- / ex-“出” + mergere → ēmergere','从浸没中出来、浮现'],['法语 émerger 或直接拉丁借入 → 英语 emerge','出现、显露、为人所知']]
def A(h,a,b):return h+[[a,b]]
WA=[
E('merge','英 /mɜːdʒ/；美 /mɜːrdʒ/','合并；汇合；融入','一条小溪汇进大河后，原来的边界消失了，两份东西成了一个整体。','借自拉丁 mergere“沉入”；由被吸收、失去独立边界，发展出合并义。',MG,'merge two files 是把两份文件内容合成一份；two lanes merge 是两条车道汇成一条。核心是原先分开的东西进入同一个整体，未必必须先有水。','merge A with B；merge into；merge two files。','mix 只要求混在一起；merge 更突出整体或边界的合一。emerge 有向外出现的 e-，不是 merge 的时态。',('Please merge the two lists into one document.','请把两份清单合成一个文档。'),('The two lanes merge just beyond the bridge.','过桥不远，两条车道汇成一条。'),sources=['https://www.etymonline.com/word/merge']),
E('merging','英 /ˈmɜːdʒɪŋ/；美 /ˈmɜːrdʒɪŋ/','正在合并；合流、汇合〔过程〕','把“成为一个整体”放到进行中的画面里。','merge 去词尾 e + -ing。',A(MG,'英语 merging','合并正在发生；合并这个过程'),'merging data 是整合原本分开的数据；merging traffic 是汇入同一车流的车辆。它可以强调过程，区别于已经形成的 merged result。','merging data；merging traffic；be merging with。','merging 不等于 emerging：前者把几部分并起来，后者说某物正在显现。',('The team is merging the records from three databases.','团队正在整合三个数据库里的记录。'),('Drivers slowed down for the merging traffic.','司机们为汇入的车流减了速。')),
E('merged','英 /mɜːdʒd/；美 /mɜːrdʒd/','已经合并的；汇合了','原来分开的几份现在已经放进同一个整体。','merge + -d。',A(MG,'英语 merged','合并后的状态；合并这一动作的过去形式'),'the merged file 是合并后的文件；the companies merged 是过去发生的合并。merged 不保证整合得完美，数据仍可能重复，文化也仍可能不同。','a merged file；merged data；the merged organisation。','merger 是合并这件事；merged 是过去动作或合并后的状态，不是同一个词性。',('The merged file still contains duplicate entries.','合并后的文件仍有重复条目。'),('The two teams merged last autumn.','两个团队在去年秋天合并了。')),
E('merger','英 /ˈmɜːdʒə/；美 /ˈmɜːrdʒər/','合并；企业合并；音位合流','把“几份并成一份”当作一件发生了的事。','与 merge 相联的法律名词形式；其历史与法语不定式作名词的习惯有关，不只是表示人的 -er。',A(MG,'英语法律名词 merger → 一般与商业用法','被吸收、归并 → 合并事件'),'a merger between two companies 是两家公司合并；语言学中的 sound merger 是原本不同的声音区别消失。常用 merger 指过程、事件或结果，不是“负责合并的人”。','a merger between；announce a merger；a proposed merger。','acquisition 偏收购控制权；merger 偏合成一体，具体商业结构仍要看上下文，不能只靠单词判法律安排。',('The merger brought two small publishers together.','这次合并把两家小出版社合在了一起。'),('The study describes a merger of two vowel sounds.','这项研究描述了两个元音的合流。'),sources=['https://www.etymonline.com/word/merger']),
E('demerge','英 /ˌdiːˈmɜːdʒ/；美 /ˌdiːˈmɜːrdʒ/','拆分；分拆企业〔商业〕','原来并在一起，现在把一个整体里的业务重新分开。','现代商业义是 de-“撤销、反向” + merge；古旧“沉下去”义另接拉丁 dēmergere。',A(MG,'现代英语 de- + merge → demerge','把合并或组合起来的业务拆开'),'demerge a company 常是把一个集团或业务拆成独立部分，不一定要求追溯到一次具体历史合并。读旧文时，另一个同形 demerge 可表示沉入，来自 de-“向下”的古典支线。','demerge a group；demerge a business from。','现代 demerge 的 de- 表反向；demersal 的 de- 表向下，两条路线不能硬用同一个中文意思套。',('The group plans to demerge its publishing business.','集团计划分拆其出版业务。'),('The company demerged into two independent firms.','这家公司拆分成了两家独立企业。'),sources=['https://www.collinsdictionary.com/dictionary/english/demerge','https://en.wiktionary.org/wiki/demerge']),
E('demerger','英 /ˌdiːˈmɜːdʒə/；美 /ˌdiːˈmɜːrdʒər/','企业分拆；分拆过程','用一个名词指“把原来合在一起的业务拆出去”这件事。','de-“反向、撤销” + merger；也可联系动词 demerge。',A(MG,'英语 de- + merger → demerger','合并 → 分拆合并体或业务的事件'),'a demerger proposal 是分拆提案。它强调组织、业务或公司结构的分离，不等于把一个文件删除，也不自动说明业务经营失败。','a proposed demerger；complete a demerger；a demerger of。','merger 把业务合在一起；demerger 把组合起来的业务拆开；不要把 -er 当成操作人员。',('The board approved the demerger of the retail division.','董事会批准了零售部门的分拆。'),('After the demerger, the two businesses operated independently.','分拆后，两项业务独立运营。'),sources=['https://dictionary.cambridge.org/dictionary/english/demerger','https://www.collinsdictionary.com/dictionary/english/demerger']),
E('emerge','英 /ɪˈmɜːdʒ/；美 /ɪˈmɜːrdʒ/','出现；浮现；显露；摆脱某状态后出现','原来被水、黑暗或信息遮住，后来露出来，让人看见。','拉丁 ē- / ex-“出来” + mergere“沉入”→ ēmergere，经法语或直接借入。',EM,'a person emerges from a tunnel 是人从隧道出来；a pattern emerges 是规律渐渐显现；it emerged that... 是后来才知道某件事。这个词通常不直接带一个被“出现”的宾语。','emerge from；emerge as；it emerged that。','appear 泛指出现；emerge 更常带原先隐藏、逐渐显露，或经历某过程后出现的感觉。',('A figure emerged from the fog.','雾中出现了一个人影。'),('A clear pattern emerged from the interviews.','访谈中逐渐显现出一个清晰的规律。'),sources=['https://www.etymonline.com/word/emerge']),
E('emerging','英 /ɪˈmɜːdʒɪŋ/；美 /ɪˈmɜːrdʒɪŋ/','正在出现的；新兴的；崭露头角的','还没完全站稳，但已经从背景里显露出来，开始受到注意。','emerge 去词尾 e + -ing。',A(EM,'英语 emerging','正在显现或成长起来的'),'emerging artists 是崭露头角的艺术家；emerging technologies 是新兴技术。这个词关注正在发展，并不保证以后一定成功或一定重要。','emerging artists；emerging technology；an emerging trend。','emergent 常也表示新出现的，另有系统与医学专门义；emerging 更直观地突出正在发生的过程。',('The festival supports emerging artists.','这个艺术节支持崭露头角的艺术家。'),('The report identifies several emerging trends.','报告指出了几种正在形成的趋势。')),
E('emerged','英 /ɪˈmɜːdʒd/；美 /ɪˈmɜːrdʒd/','出现了；显露了；以某种身份脱颖而出','原先没看见的事已经露出来，或者竞争之后结果已经显现。','emerge + -d。',A(EM,'英语 emerged','浮现这一动作的过去式、过去分词'),'emerged as the leader 是最终显现为领头者；new details emerged 是新细节被揭示。通常说 details emerged，不说 details were emerged。','emerged from；emerged as；new evidence emerged。','emerged 常以事物自己显露的方式表达；revealed 常把揭示者或揭示动作放进句子。',('New details emerged during the second interview.','第二次访谈中出现了新的细节。'),('She emerged as the strongest candidate.','她脱颖而出，成为实力最强的候选人。')),
E('emergence','英 /ɪˈmɜːdʒəns/；美 /ɪˈmɜːrdʒəns/','出现；兴起；涌现','一件事从没有被看见，到作为明显现象站出来的过程。','经法语 émergence，接拉丁 ēmergere；现代可按 emerge + -ence 记。',EM[:2]+[['法语 émergence → 英语 emergence','浮现、意外出现 → 出现、兴起；与 emergency 后来分工']],'the emergence of a movement 是某运动的兴起。系统研究中的 emergence 常说许多部分相互作用后出现整体模式，例如许多鸟相互调整形成群飞形状；不能简单把它当作“凭空冒出来”。','the emergence of；the emergence of a pattern；gradual emergence。','emergency 是需要及时处理的紧急情况；emergence 通常只是出现、兴起，不自带危险义。',('The book traces the emergence of modern cities.','这本书追溯了现代城市的兴起。'),('Researchers observed the emergence of a stable pattern.','研究人员观察到一种稳定模式逐渐出现。'),sources=['https://www.etymonline.com/word/emergence']),
E('emergency','英 /ɪˈmɜːdʒənsi/；美 /ɪˈmɜːrdʒənsi/','紧急情况；突发急事','事情突然冒出来，而且不能照原计划慢慢等，需要及时应对。','接拉丁 ēmergere“出现”、分词 ēmergēns 的词族；也按 emerge + -ency 分析。',EM[:2]+[['英语 emergency','突然出现的情况 → 需要立即应对的紧急情况']],'emergency exit 是紧急出口；an emergency meeting 是为紧急事项召开的会议。与 emergence 同根，但现代 emergency 已把重点放在情况的紧迫性。','in an emergency；an emergency exit；emergency services。','urgent 是形容事情急；emergency 是紧急情形本身。普通新情况可以 emerge，却未必构成 an emergency。',('Keep the emergency exit clear.','请保持紧急出口畅通。'),('The team held an emergency meeting that evening.','团队当晚召开了紧急会议。'),sources=['https://www.etymonline.com/word/emergency']),
E('emergent','英 /ɪˈmɜːdʒənt/；美 /ɪˈmɜːrdʒənt/','新出现的；涌现的；挺出水面的〔植物〕；紧急的〔医疗用语〕','可以是正在显现的新东西，也可以是许多部分互动后才出现的整体特点。','拉丁 ēmergēns“正在出现的”借入；医疗中的紧急义受 emergency 影响。',A(EM[:2],'英语 emergent','正在出现、露出的 → 新兴、整体涌现的；另有紧急义'),'emergent properties 是由组成部分的互动显现的整体性质，不能只逐个看零件就照搬它们的性质。emergent plants 则是从水面挺出的植物。医疗里 emergent 可指需紧急处理，要看领域。','emergent properties；emergent behaviour；emergent vegetation。','emerging 和 emergent 常有重合，但 emergent behaviour 的系统含义，不是单纯给 emerging 换个词尾。',('The model shows emergent behaviour from simple rules.','这个模型由简单规则产生了整体层面的行为模式。'),('Emergent plants grow along the shallow edge of the pond.','池塘浅水边缘长着挺水植物。'),sources=['https://en.wiktionary.org/wiki/emergent#English','https://www.merriam-webster.com/dictionary/emergent']),
E('reemerge','英 /ˌriːɪˈmɜːdʒ/；美 /ˌriːɪˈmɜːrdʒ/','重新出现；再度浮现','曾经露过面，后来藏起来或沉下去，现在又出来了。','re-“再次” + emerge。',A(EM,'英语 reemerge','再次显露、出现'),'问题暂时消失后又冒出来，可以说 reemerge；人从后台再次出现也可这样说。拼写中连着两个 e，分别属于 re- 和 emerge。','reemerge from；reemerge as；a problem reemerges。','reappear 强调再出现；reemerge 常多一层被隐藏、被遮住或暂时退出视野的感觉。',('The sun reemerged from behind the clouds.','太阳重新从云层后面露出来。'),('The same problem reemerged a month later.','同样的问题一个月后又出现了。')),
E('reemergence','英 /ˌriːɪˈmɜːdʒəns/；美 /ˌriːɪˈmɜːrdʒəns/','重新出现；再度兴起','把“又露出来”这件事作为一个过程或现象来谈。','re-“再次” + emergence。',A(EM,'英语 emergence → reemergence','出现 → 再次出现'),'the reemergence of an idea 可指一个沉寂的想法再受关注；the reemergence of cracks 是裂缝修过后又出现。它不一定说完全相同的个体回来了，也可以是同类现象复现。','the reemergence of；prevent the reemergence。','resurgence 更常强调重新增强、复兴；reemergence 首先只说重新露面。',('The article examines the reemergence of an old debate.','这篇文章讨论了一场旧争论的再度出现。'),('The reemergence of cracks suggested that the repair had not solved the problem.','裂缝再次出现，说明修补并未解决问题。')),
E('emersion','英 /ɪˈmɜːʃən/；美 /iːˈmɜːrʒən/','露出；出水；复现〔天文等专门用语〕','藏在水下或被别的天体遮住的东西，再度露出来。','拉丁 ēmersus，ēmergere“浮出”的分词词干，接名词形式。',M+[['拉丁 ēmergere → ēmersus → 英语 emersion','浮出 → 露出、复现的过程']],'天文学里可指被遮挡的天体重新显现；海岸生态语境里可说退潮后生物露在空气中的阶段。它较专门，普通“某个潮流的兴起”通常用 emergence。','emersion from water；the time of emersion。','immersion 是浸入，emersion 是露出；有些口音读音很近，拼写和方向必须分清。',('The astronomer recorded the star’s emersion from behind the Moon.','天文学家记录了恒星从月球后方重新显现的时刻。'),('The study measured how long the organisms survived emersion.','这项研究测量了这些生物露出水面后能存活多久。'),sources=['https://www.merriam-webster.com/dictionary/emersion','https://en.wiktionary.org/wiki/emersion']),
E('merganser','英 /mɜːˈɡænsə/；美 /mɜːrˈɡænsər/','秋沙鸭','把一只会潜下去追鱼的水鸟记成“潜水的鹅”，就能抓住这个旧命名的画面。','新拉丁 merganser：拉丁 mergus“潜水水鸟” + anser“鹅”；mergus 接 mergere“浸入”。',M+[['拉丁 mergus + anser → 新拉丁 merganser → 英语 merganser','潜水水鸟 + 鹅 → 秋沙鸭名称']],'秋沙鸭是鸭类水鸟，名字里有 anser“鹅”不等于现代分类把它当家鹅。长而较窄的喙、潜水捕食的习性，能帮助把这个少见鸟名记牢。','a common merganser；a flock of mergansers。','merger 是合并，merganser 是鸟名；这里的 g 通常读 /ɡ/，不是 merge 里的 /dʒ/。',('A merganser dived beneath the surface of the lake.','一只秋沙鸭潜入了湖面下。'),('We watched several mergansers fishing near the shore.','我们看着几只秋沙鸭在岸边附近捕鱼。'),sources=['https://www.etymonline.com/word/merganser','https://www.merriam-webster.com/dictionary/merganser','https://www.allaboutbirds.org/guide/Common_Merganser/overview']),
]
